def reflection(country,person,recipe):
 _,cap,picture,next_action=recipe
 return {'Affirmation':f'I can {cap} for {country}, one evidence-based decision at a time.','Visualization':f'I picture {picture}, with {person}’s fictional case making the impact clear.','Gratitude':f'I am grateful for the questions, source material and careful review that help me {cap} responsibly.','Intention':f'I will {next_action}, then record what the result teaches me.'}

