def strip_old_audio(s):
 s=re.sub(r'<div class="musicbar">.*?</div>','',s,count=1,flags=re.S)
 # Preserve daily quotes, replace the generated melody portion only.
 def brand(m):
  body=m.group(2)
  if 'let ctx,gain,timer' in body:body=body.split('let ctx,gain,timer',1)[0]+'})();'
  return m.group(1)+body+'</script>'
 s=re.sub(r'(<script id="sla-brand-script">)(.*?)</script>',brand,s,flags=re.S)
 lines=s.splitlines()
 for i,line in enumerate(lines):
  if line.startswith('function reflection(){') and '<h3>Focus sound' in line:
   lines[i]=line.split("+'</div><div class=\"card\"><h3>Focus sound",1)[0]+"+'</div>'}"
  elif line.startswith('let audioContext=null,audioNodes=[];') or line.startswith('async function startSound(kind)'):lines[i]=''
  elif line.startswith('function bindReflection(){'):lines[i]="function bindReflection(){document.querySelectorAll('[data-reflect]').forEach(t=>t.oninput=()=>{S.reflection[t.dataset.reflect]=t.value;save()})}"
 return '\n'.join(lines)

def main():
 catalog=json.loads((REPO/'payroll-catalog.json').read_text());profiles={};payloads={};report=[];fixture_count=0
 standard=[r for r in catalog['resources'] if r['kind']!='configurator']
 for row in standard:
  path=REPO/row['path'];s=path.read_text();match=re.search(r'<script type="application/json" id="workbook-data">(.*?)</script>',s,re.S);d=json.loads(match.group(1));c=dataset(row,d['profile']);app=row['kind']=='replication';reflections={}
  fixture_count+=len(d['modules']);row['sections']=len(d['modules'])
  for m in d['modules']:
   n=m['n'];recipe=(APP_RECIPES if app else MAIN_RECIPES)[n-1]
